// Generated by Tempo — do not edit.
// Ties the canvas devserver's lifetime to the Tempo app: the app holds this
// process's stdin open; when the app dies (cleanly or not) the OS closes the
// pipe, and the watchdog kills the devserver tree so no orphan is left
// holding Next.js's per-directory dev lock.
"use strict";
const { spawn, spawnSync } = require("node:child_process");

const command = process.argv[2];
if (!command) {
  process.stderr.write("devserver-watchdog: missing command argument\n");
  process.exit(64);
}

const childEnv = { ...process.env };
const childRunAsNode = childEnv.TEMPO_WATCHDOG_CHILD_ELECTRON_RUN_AS_NODE;
delete childEnv.TEMPO_WATCHDOG_CHILD_ELECTRON_RUN_AS_NODE;
if (childRunAsNode === "__TEMPO_UNSET__") {
  delete childEnv.ELECTRON_RUN_AS_NODE;
} else if (childRunAsNode !== undefined) {
  childEnv.ELECTRON_RUN_AS_NODE = childRunAsNode;
}

const child = spawn(command, {
  shell: true,
  detached: process.platform !== "win32",
  windowsHide: true,
  stdio: ["ignore", "inherit", "inherit"],
  env: childEnv,
});

// Tell the supervisor which process is the real managed process-group root.
// The watchdog itself is only a lifetime relay; persisting its pid would make
// the next app instance unable to prove that the port listener belongs to the
// tree Tempo launched. IPC is intentionally optional so the generated script
// remains independently runnable in focused watchdog tests.
if (typeof process.send === "function") {
  process.send({ type: "tempo-watchdog-child", pid: child.pid ?? null });
}

let killed = false;
function killTree() {
  if (killed || child.pid == null) return;
  killed = true;
  if (process.platform === "win32") {
    spawnSync("taskkill", ["/pid", String(child.pid), "/t", "/f"], {
      stdio: "ignore",
      windowsHide: true,
    });
  } else {
    try { process.kill(-child.pid, "SIGKILL"); } catch {}
    try { process.kill(child.pid, "SIGKILL"); } catch {}
  }
}

child.on("exit", (code) => {
  // Forward the devserver's exit code verbatim (full DWORD range on
  // Windows) so the supervisor's crash classification sees the real code.
  process.exit(code === null ? 1 : code);
});

// The death signal: stdin EOF means the Tempo app is gone.
process.stdin.resume();
const onParentGone = () => {
  killTree();
  process.exit(0);
};
process.stdin.on("end", onParentGone);
process.stdin.on("close", onParentGone);
process.stdin.on("error", onParentGone);

// Graceful teardown paths (the supervisor's stop / signal flows) must also
// take the tree down, not just the watchdog.
for (const signal of ["SIGTERM", "SIGINT", "SIGHUP"]) {
  process.on(signal, onParentGone);
}
